teri: snippet (JS) for 429 handling I dropped into the branch:
```js
// simple retry with jitter
async function callGen(payload){
  let wait=200;
  for(let i=0;i<5;i++){
    const r=await fetch('https://api.redwood.ai/v1/generate',{method:'POST',headers:{'Authorization':`Bearer ${process.env.REDWOOD_API_KEY}`,'x-redwood-consumption-unit':'token','Content-Type':'application/json'},body:JSON.stringify(payload)});
    if(r.status===429){await new Promise(s=>setTimeout(s,wait+Math.random()*100));wait*=2;continue;}
    return r.json();
  }
  throw new Error('retries exhausted');
}
```

